// Proposal for the agreed node 10.14, "What is generated from the nodes is regenerated and never edited"
// (s-kh8qcd5kxgh9z3j), carrying out the plan the owner accepted on 2026-11-17: the list of the export, the map and the
// instructions an agent reads moves from the text into an example, and the text names code generated into the system's
// code as the exception that 10.15 describes.
import fs from "node:fs";

const here = new URL(".", import.meta.url);
const file = new URL("newform.json", here);
fs.copyFileSync(file, new URL("newform.before-propose-10-14.json", here));
const d = JSON.parse(fs.readFileSync(file, "utf8"));
const n = d["10.14"];
if (n.proposals?.length) throw new Error("10.14 already holds a proposal");
n.proposals = [{
  where: "Текст и пример",
  en: [
    "Title: What is generated from the nodes is regenerated and never edited",
    "Text: The SpecSheriff tools regenerate whatever is generated from the nodes after every change to them. What is generated into the system's code is the exception: it waits for the approval of its nodes (§s-qyjw8xez6t6adc3).",
    "Nobody edits anything generated by hand. Nobody copies anything from what is generated back into the specification.",
    "Example: A readable export, for example in Markdown, the map of the specification and the instructions an agent reads are regenerated after every change to the nodes.",
    "Reason: " + n.reason,
  ].join("\n\n"),
  ru: [
    "Заголовок: " + n.ruTitle,
    "Текст: Инструменты SpecSheriff заново генерируют всё, что генерируется из узлов, после каждого изменения узлов. Исключение — то, что генерируется в код системы: оно ждёт одобрения своих узлов (§s-qyjw8xez6t6adc3).",
    "Вручную сгенерированное никто не редактирует. Никто ничего не переносит из сгенерированного обратно в спецификацию.",
    "Пример: После каждого изменения узлов заново генерируются читаемый экспорт, например в Markdown, карта спецификации и инструкции, которые читает агент.",
    "Обоснование: " + n.ruReason,
  ].join("\n\n"),
  why: "Перечень «экспорт, карта, инструкции агента» уходит из текста в пример: экспорт и карта теперь относятся к расширению «Представления спецификации», а текст правила guidelines понятий расширения не называет, пример — может (1.7.4, 1.7.3). Добавлено исключение для кода: 10.15 стоит сразу после 10.14 как исключение из него, и без этой фразы 10.14 требовал бы генерировать заново и код, который ждёт одобрения своих узлов. «Вручную это никто не редактирует» стало «вручную сгенерированное никто не редактирует»: между этой фразой и тем, к чему относилось «это», теперь стоит фраза об исключении. Обоснование не меняется.",
}];
fs.writeFileSync(file, JSON.stringify(d, null, 2) + "\n");
console.log("ok");
